package com.gathin.tvhome;

import android.app.Activity;
import android.content.Intent;
import android.media.session.PlaybackState;
import android.os.Bundle;
import android.widget.*;

/** Optional player panel; every transport command comes from an explicit button press. */
public final class NowPlayingActivity extends Activity {
    private NowPlaying.Lease lease;private TextView title,pause,next,previous,open,access;
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private TextView button(LinearLayout host,String name,Runnable action){TextView view=new TextView(this);view.setTypeface(SettingsTypography.regular(this));view.setText(name);view.setTextSize(20);view.setTextColor(getColor(R.color.freedom_text));view.setPadding(dp(20),dp(14),dp(20),dp(14));view.setMinHeight(dp(52));view.setFocusable(true);view.setFocusableInTouchMode(true);view.setClickable(true);view.setBackgroundResource(R.drawable.settings_choice_bg);view.setOnClickListener(v->{try{action.run();}catch(Exception changed){Toast.makeText(this,"The media session changed. Open its app to continue.",Toast.LENGTH_LONG).show();}});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);host.addView(view,p);return view;}
    @Override protected void onCreate(Bundle saved){super.onCreate(saved);Config.load(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(80),dp(40),dp(80),dp(30));root.setBackgroundColor(getColor(R.color.freedom_canvas));TextView heading=new TextView(this);heading.setText("Now Playing");heading.setTypeface(SettingsTypography.heading(this));heading.setTextSize(30);heading.setTextColor(getColor(R.color.freedom_text));root.addView(heading);title=new TextView(this);title.setTextColor(getColor(R.color.freedom_secondary));title.setTextSize(20);title.setTypeface(SettingsTypography.regular(this));title.setPadding(0,dp(20),0,dp(12));root.addView(title);
        pause=button(root,"Play / pause",()->{if(lease.selected==null)return;PlaybackState state=lease.selected.getPlaybackState();if(lease.action(state!=null&&state.getState()==PlaybackState.STATE_PLAYING?PlaybackState.ACTION_PAUSE:PlaybackState.ACTION_PLAY)){if(state!=null&&state.getState()==PlaybackState.STATE_PLAYING)lease.selected.getTransportControls().pause();else lease.selected.getTransportControls().play();}else if(lease.action(PlaybackState.ACTION_PLAY_PAUSE)){lease.selected.dispatchMediaButtonEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN,android.view.KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE));lease.selected.dispatchMediaButtonEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_UP,android.view.KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE));}});
        previous=button(root,"Previous",()->{if(lease.action(PlaybackState.ACTION_SKIP_TO_PREVIOUS))lease.selected.getTransportControls().skipToPrevious();});next=button(root,"Next",()->{if(lease.action(PlaybackState.ACTION_SKIP_TO_NEXT))lease.selected.getTransportControls().skipToNext();});
        open=button(root,"Open media app",()->{if(lease.selected==null)return;Intent intent=getPackageManager().getLeanbackLaunchIntentForPackage(lease.selected.getPackageName());if(intent!=null)startActivity(intent);});access=button(root,"Access and display settings",()->NowPlaying.settings(this));button(root,"Back",this::finish);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(root);setContentView(scroll);pause.requestFocus();}
    @Override protected void onResume(){super.onResume();lease=new NowPlaying.Lease(this,this::paint);lease.start();paint();}
    private void available(TextView view,boolean on){view.setEnabled(on);view.setFocusable(on);view.setAlpha(on?1:.45f);}
    private void paint(){boolean active=lease.selected!=null;for(TextView control:new TextView[]{pause,previous,next,open})control.setVisibility(active?android.view.View.VISIBLE:android.view.View.GONE);String label=lease.title();title.setText(label.isEmpty()?NowPlaying.enabled(this)?"No supported media is active in this profile. Play something in a visible app, then return here.":"Now Playing is off or Android access is unavailable. Open Access and display settings to review the requirements.":label);boolean playing=lease.selected!=null&&lease.selected.getPlaybackState()!=null&&lease.selected.getPlaybackState().getState()==PlaybackState.STATE_PLAYING;pause.setText(playing?"Pause":"Play");available(pause,lease.action(playing?PlaybackState.ACTION_PAUSE:PlaybackState.ACTION_PLAY)||lease.action(PlaybackState.ACTION_PLAY_PAUSE));available(next,lease.action(PlaybackState.ACTION_SKIP_TO_NEXT));available(previous,lease.action(PlaybackState.ACTION_SKIP_TO_PREVIOUS));available(open,lease.selected!=null);if(getCurrentFocus()==null||!getCurrentFocus().isEnabled())access.requestFocusFromTouch();}
    @Override protected void onPause(){if(lease!=null)lease.close();super.onPause();}
}
